XPCOMUtils.defineLazyPreferenceGetter(
  lazy,
  "enabledActions",
  "mail.biff.alert.enabled_actions",
  "",
  null,
  val => {
    const actions = [];
    for (const name of val.split(",")) {
      const action = availableActions.find(a => a.action == name);
      if (action) {
        if (!action.title) {
          action.title = lazy.l10n.formatValueSync(action.l10nId);
        }
        actions.push(action);
      }
    }
    return actions;
  }
